typedef unsigned int size_t;
#define NULL 0

class stringx {
public:
  typedef unsigned int size_type;
  static const size_type npos = (size_type)-1;
  stringx();
  stringx(const stringx&);
  ~stringx();
  stringx& operator=(const stringx&);
  size_type find(size_type, char) const;
  stringx substr(size_type, size_type) const;
  stringx& operator+=(const char*);
};

class vector3d {
public:
  float x, y, z;
  vector3d& operator=(const vector3d&);
};
extern const vector3d ZEROVEC;

class chunk_file {
public:
  chunk_file();
  ~chunk_file();
  void open(const stringx&);
};

template<class T> class vector {
  T* start;
  T* finish;
  T* end_of_storage;
};
template<class K, class V> class map { char data[24]; };

class visual_rep { char data[20]; };
class vert;
class hw_rasta_vert;
class wedge;
class face;
class reduced_face;
class material;
class bone;
typedef unsigned short vert_ref;
typedef unsigned short wedge_ref;
typedef unsigned short face_ref;

class vr_pmesh : public visual_rep {
public:
  enum { LIT_LAST_FRAME = 4 };
private:
  vector<vert>* verts;
  hw_rasta_vert* xverts;
  wedge* wedges;
  int min_faces;
  int* xverts_for_lod;
  int num_wedges;
  face* faces;
  reduced_face* reduced_faces;
  int num_faces;
  vector<material*> materials;
  vert_ref* vert_refs_for_wedge_ref;
  wedge_ref* wedge_index_list;
  short* wedge_lod_starts;
  face_ref* original_face_for_face_slot;
  map<short, unsigned short> material_changes;
  vector<bone> bones;
  bool has_translucent_verts;
  bool progressive;
  short alignment;
  int uvanim_update_frame;
  vector3d center;
  float radius;
  vector3d pivot;
  int pivot_valid;
  stringx filename;
  unsigned mesh_flags;
public:
  int max_detail;
  int min_detail;
  void internal_serial_in(chunk_file&);
  void _construct(const stringx&, unsigned);
};

void vr_pmesh::_construct(const stringx& pmesh_filename, unsigned _mesh_flags )
{
  has_translucent_verts = false;
  mesh_flags = _mesh_flags | LIT_LAST_FRAME;

  // <<<< most of the asserts in this file should give warnings about
  //      where file is corrupt to user, that is if this remains a text file
  //      that people touch
  verts = NULL;
  xverts = NULL;
  uvanim_update_frame = 0;
  wedges = NULL;
  vert_refs_for_wedge_ref = NULL;
  wedge_lod_starts = NULL;
  original_face_for_face_slot = NULL;
  faces = NULL;
  wedge_index_list = NULL;
  reduced_faces = NULL;
  pivot = ZEROVEC;
  pivot_valid = false;
  xverts_for_lod = NULL;

  chunk_file fs;

  // use ".txtmesh" extension no matter what
  stringx adjusted_pmesh_filename;
  stringx::size_type dot_pos = pmesh_filename.find( 0, '.' );
  if( dot_pos != stringx::npos )
    adjusted_pmesh_filename = pmesh_filename.substr( 0, dot_pos );
  else
    adjusted_pmesh_filename = pmesh_filename;
  adjusted_pmesh_filename += ".txtmesh";

  fs.open(adjusted_pmesh_filename);
  internal_serial_in( fs );
  filename = pmesh_filename;
}
